d":4030,"materia":"ling","nivel":0,"enunciado":"O documento em que a pessoa apresenta sua formação e experiência ao procurar emprego é o:","opcoes":["Currículo","Editorial","Conto","Sermão"],"explicacao":"Gênero textual objetivo e organizado em tópicos."},{"id":4031,"materia":"ling","nivel":1,"enunciado":"A linguagem conotativa é aquela usada:","opcoes":["Em sentido figurado","Sempre em sentido literal","Apenas em dicionários","Só em textos científicos"],"explicacao":"A denotativa é a do sentido literal."},{"id":4032,"materia":"mat","nivel":1,"enunciado":"Uma receita pede 200 g de farinha para 10 biscoitos. Para 25 biscoitos, são necessários:","opcoes":["500 g","400 g","250 g","450 g"],"explicacao":"200 × 25 ÷ 10."},{"id":4033,"materia":"mat","nivel":1,"enunciado":"Um tanque de 60 litros está com 3/4 da capacidade. Ele contém:","opcoes":["45 litros","40 litros","15 litros","20 litros"],"explicacao":"60 ÷ 4 × 3."},{"id":4034,"materia":"mat","nivel":2,"enunciado":"O número 0,000005 em notação científica é:","opcoes":["5 × 10⁻⁶","5 × 10⁻⁵","5 × 10⁶","0,5 × 10⁻⁶"],"explicacao":"Vírgula anda 6 casas para a direita."},{"id":4035,"materia":"mat","nivel":3,"enunciado":"Uma escada rolante sobe 6 m de altura e tem 10 m de comprimento. A distância horizontal que ela ocupa é:","opcoes":["8 m","4 m","16 m","12 m"],"explicacao":"Pitágoras: 10² − 6² = 64."},{"id":4036,"materia":"mat","nivel":4,"enunciado":"Uma loja vende um produto por R$ 300,00 à vista ou R$ 330,00 em 3 parcelas. O acréscimo no parcelado é de:","opcoes":["10%","30%","3%","33%"],"explicacao":"30 a mais sobre 300."},{"id":4037,"materia":"geo","nivel":1,"enunciado":"A massa de ar que traz frio e geadas ao Sul do Brasil no inverno é a:","opcoes":["Massa Polar Atlântica","Massa Equatorial Continental","Massa Tropical Atlântica","Massa Equatorial Atlântica"],"explicacao":"Vem do sul do continente."},{"id":4038,"materia":"bio","nivel":2,"enunciado":"As briófitas, como os musgos, são plantas que:","opcoes":["Não têm vasos condutores de seiva","Produzem flores e frutos","São as maiores árvores do mundo, como as sequoias","Têm sementes sem fruto"],"explicacao":"Vivem em locais úmidos e são pequenas."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('ling','mat','fis','qui','bio','his','geo','fil') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
